-- TASK-373 | KS 60 evidence-based educational explanations
-- Review proposal ONLY. NEVER execute against production. NOT a migration.
-- Published rows, keys and historical attempts are immutable.
-- The user explicitly allows GitHub main merge ONLY, NO production database writes or deploy.
-- Any deliberate execution of this file remains transactionally rolled back.
BEGIN;
SET LOCAL lock_timeout='10s';
SET LOCAL statement_timeout='120s';

CREATE TEMP TABLE task373_ks_explanations (
  source_reference text PRIMARY KEY,
  educational_explanation text NOT NULL CHECK(char_length(trim(educational_explanation))>=190)
) ON COMMIT DROP;


DO $task373$
DECLARE
  item record;
  v_actor uuid;
  v_successor uuid;
  n integer;
BEGIN
  SELECT count(*) INTO n FROM task373_ks_explanations;
  IF n <> 60 THEN RAISE EXCEPTION 'TASK373_EXPECTED_60'; END IF;

  SELECT count(*) INTO n FROM public.profiles
  WHERE role='admin' AND NOT coalesce(is_blocked,false);
  IF n <> 1 THEN RAISE EXCEPTION 'TASK373_UNIQUE_ACTIVE_ADMIN_REQUIRED'; END IF;
  SELECT id INTO STRICT v_actor FROM public.profiles
  WHERE role='admin' AND NOT coalesce(is_blocked,false);

  SELECT count(*) INTO n
  FROM task373_ks_explanations t
  JOIN public.questions q ON q.source_reference=t.source_reference
  JOIN public.question_keys k ON k.question_id=q.id
  WHERE q.status='published'
    AND q.group_code='KS'
    AND q.format='Y1'
    AND char_length(trim(coalesce(k.explanation_md,''))) < 80
    AND NOT EXISTS (
      SELECT 1 FROM public.pedagogy_revision_queue r WHERE r.source_question_id=q.id
    );
  IF n <> 60 THEN RAISE EXCEPTION 'TASK373_SOURCE_DRIFT_OR_ALREADY_REVISED_%',n; END IF;

  FOR item IN
    SELECT q.id,t.educational_explanation
    FROM task373_ks_explanations t
    JOIN public.questions q ON q.source_reference=t.source_reference
    ORDER BY t.source_reference
  LOOP
    VALUES(item.id,'TASK-373: substantive KS explanation prepared for independent human expert review');
    v_successor := public.stage_pedagogy_revision(item.id,v_actor);
    UPDATE public.question_keys
       SET explanation_md=item.educational_explanation,updated_at=now()
     WHERE question_id=v_successor;
    GET DIAGNOSTICS n=ROW_COUNT;
    IF n <> 1 OR NOT EXISTS (
      SELECT 1 FROM public.questions
      WHERE id=v_successor AND status='review'
    ) THEN RAISE EXCEPTION 'TASK373_REVIEW_CLONE_NOT_CREATED'; END IF;
  END LOOP;
END $task373$;

-- This proposed workflow has never been run in production.
-- No published row update, no owner waiver, no publish, no commit.
ROLLBACK;
