INSERT INTO task373_ks_explanations(source_reference,educational_explanation) VALUES
  ('authored:ai-assisted:m14-closed-20261018:kasb-standarti:page-2:topic-1:question-2', 'Bir xil mavzuni turli yoshdagi sinflarda o‘rgatish uchun maqsad saqlangan holda faoliyatning murakkabligi, misollar va yordam darajasi o‘quvchilar rivojiga moslanadi. Kichik sinfga konkret tasvir, katta sinfga mustaqil tahlil berish mumkin. Faqat vaqt yoki o‘qituvchi kayfiyatiga qarab farqlash yoshga mos rejalashtirish emas.'),
  ('authored:pedagogy-pdf-corpus:v3:2026:spring:p1:q1', 'Sinfda qiziqish va tayyorgarlik darajasi farq qilsa, o‘qituvchi ta’lim dasturining talab etilgan maqsadlarini saqlab, o‘qitish sur’ati, misollar va mashqlarni zaruratga ko‘ra moslashtiradi. Shu orqali turli o‘quvchilar mazmunli ishtirok etadi. Rejani hamma uchun o‘zgartirmasdan bir xil berish ehtiyojlarni hisobga olmaydi.'),
  ('authored:pedguli-html-concepts:v3:KS.01:201', '«O‘quvchi mavzuni biladi» degan natija kuzatiladigan harakatni bildirmaydi, shu sabab baholashga yaroqsiz. Uni «o‘quvchi berilgan grafikda uchta xatoni aniqlab, sababini izohlaydi» kabi amal va mezon bilan yozish kerak. Bu o‘qituvchiga topshiriq hamda baholash dalilini oldindan mos rejalash imkonini beradi.'),
  ('authored:pedguli-topic-study:v2:KS.01:101', '«Algoritmda uch turdagi xatoni aniqlab tuzata oladi» iborasi o‘quvchining aniq kuzatiladigan ishini va natija mezonini belgilaydi. Tekshiruvda berilgan algoritm va xato turlari yordamida bu ko‘nikmani baholash mumkin. «Algoritmni tushunadi» kabi umumiy jumla o‘quvchi nimani bajara olishini ochib bermaydi.'),
  ('authored:pedguli-topic-study:v2:KS.02:102', 'Loyiha jarayonida yakuniy mahsulot bilan birga o‘quvchining izlanishi, dalil to‘plashi, hamkorlik qilishi va muammoni bosqichma-bosqich hal etishi ham muhim. Faqat mahsulotni baholash shu rivojlanish jarayoni haqida dalil bermaydi. Kuzatuv varaqasi va oraliq hisobotlar jarayonni xolisroq ko‘rsatishi mumkin.'),
  ('authored:pedguli-topic-study:v2:KS.03:103', 'Ikki o‘quvchi bir xil noto‘g‘ri natijaga kelgan bo‘lsa ham, biri qoidani bilmasligi, ikkinchisi hisob bosqichini adashtirishi mumkin. Qayta aloqa xatoning tashqi ko‘rinishiga emas, aniqlangan sababga tayanishi kerak. Biriga tushuncha misoli, boshqasiga tekshirish mashqi berish individual yordamni aniqroq qiladi.'),
  ('authored:pedguli-topic-study:v2:KS.04:104', 'Guruh taqdimotida ovozi kamroq eshitilayotgan o‘quvchini chetda qoldirmasdan, hurmatli suhbat qoidalarini kelishish va ishtirok navbatini adolatli taqsimlash zarur. Bu bolaning sha’nini saqlaydi va fikr bildirishga xavfsiz imkon beradi. Faol ishtirokchini ayblash yoki sustroq o‘quvchini majburan tanqid qilish tarbiyaviy maqsadga xizmat qilmaydi.'),
  ('authored:pedguli-topic-study:v2:KS.06:107', 'Yangi interfaol metod kutilgan natija bermasa, uni darhol muvaffaqiyatsiz deb rad etish ham, natijani e’tiborsiz qoldirish ham yetarli emas. Pedagog o‘quvchi ishlari va fikrini tahlil qilib, aynan nima ishlamaganini aniqlaydi, so‘ng metodni qayta moslashtirib sinaydi. Dalilga tayangan takomillashtirish kasbiy refleksiyaning amaliy belgisi.'),
  ('authored:pedguli-topic-study:v2:KS.07:108', 'Ota-ona va ikki fan o‘qituvchisi mustaqil loyihada birga ishlaganda avval o‘quv natijasi, kim qaysi ishga mas’ul ekani va qanday mezon bilan baholanishi kelishiladi. O‘quvchiga tegishli shaxsiy ma’lumotlar esa faqat zarur doirada ulashiladi. Aniq kelishuv bo‘lmasa vazifalar takrorlanishi yoki maxfiylik buzilishi mumkin.'),
  ('authored:professional-15:v1:KS.01:1', 'Dars rejalashtirishda avvalo o‘quvchi mashg‘ulot oxirida qaysi bilim yoki ko‘nikmani namoyish eta olishi belgilanadi. Shundan so‘ng faoliyat, vaqt, metod va baholash shu natijaga mos tanlanadi. Agar reja faqat mavzu nomi yoki vositadan boshlansa, natijaga erishilganini qanday tekshirish noaniq qolishi mumkin.'),
  ('authored:professional-15:v1:KS.01:2', 'Boshlang‘ich diagnostika o‘quvchilarning bir mavzudagi tayanch bilimlari turlicha ekanini ko‘rsatgan. Shuning uchun bir xil qiyin topshiriq o‘rniga tayanch mashq, ko‘mak va kengaytirilgan vazifani ehtiyojga mos ajratish asosli. Bu differensial rejalash hammani bitta maqsad sari o‘z imkoniyati darajasidan rivojlantirishga xizmat qiladi.'),
  ('authored:professional-15:v1:KS.02:3', 'Darsdagi faol ishtirok faqat tinglash yoki guruhga ajralish bilan yuzaga kelmaydi. O‘quvchilar yechimni ishlab chiqib, sababini bir-biriga tushuntiradigan vazifa ulardan fikrlash, muloqot va bilimni qo‘llashni talab etadi. Shuning uchun hamkorlikdagi mazmunli topshiriq passiv ma’ruza bilan solishtirganda ko‘proq ishtirok imkonini yaratadi.'),
  ('reserve-2026:T060-R4-KS-B01', 'Kutiladigan o‘quv natijasi rejaning yo‘nalishini belgilaydi: masalan, «o‘quvchi shart operatori bilan masala yecha oladi» deyilsa, mashq va baholash shu amaliy harakatga mos tuziladi. Natija avval aniqlanmasa, metodlar tasodifiy tanlanib, dars oxirida nimani tekshirish kerakligi mavhum qolishi mumkin.'),
  ('revision:pedagogy:011100a0-eae8-499e-b495-9188867ef360', 'Pedagogik diagnostika o‘quvchi yoki sinfning boshlang‘ich bilim darajasi, tushunmovchiligi va ehtiyojlarini dalil orqali aniqlaydi. Uning natijasi keyingi dars sur’ati hamda yordamni rejalashga xizmat qiladi. Bu faqat yakuniy baho qo‘yishdan farq qiladi, chunki asosiy maqsad qiyinchilik sababini topish va ta’limni moslashtirishdir.'),
  ('revision:pedagogy:0d556a8a-124f-4c79-b415-803e9f7ddd56', 'Baholashdan olingan dalil faqat jurnalga kiritilsa, ta’limni yaxshilash imkoniyati ishlatilmay qoladi. O‘qituvchi qaysi ko‘nikma sustligini aniqlab, mashqlar, tushuntirish va yordamni shu natijaga mos yangilashi kerak. Formativ baholash sikli aynan dalil, pedagogik qaror va qayta tekshirish orqali yakunlanadi.'),
  ('revision:pedagogy:10b68383-9377-49e0-8526-31b0511896a9', 'Kasbiy rivojlanish rejasini tuzish uchun o‘qituvchi avvalo darsdagi kuchli tomonlari va yaxshilashga muhtoj ishlarini dalil bilan tahlil qiladi. O‘quvchi natijalari, dars kuzatuvi va hamkasb fikri bu ehtiyojni ochadi. Muammo aniqlanmasdan kurs yoki metod tanlash maqsadsiz bo‘lishi mumkin; refleksiya rivojlanishning boshlang‘ich bosqichidir.'),
  ('revision:pedagogy:113b9be5-5f96-4895-9c7b-d25c7416dd49', 'Eshitishida qiyinchiligi bo‘lgan o‘quvchi faqat og‘zaki ko‘rsatma orqali vazifani to‘liq anglamasligi mumkin. Shuning uchun topshiriqni yozma matn, piktogramma yoki bosqichli namuna bilan ham ko‘rsatish kerak. Bu o‘quv maqsadini pasaytirmaydi, balki axborotga teng kirish va mustaqil bajarish imkonini oshiradi.'),
  ('revision:pedagogy:1a3b7a49-3aa5-4209-bea1-83c82b319f32', 'Dars maqsadida «grafikni tahlil qilish» belgilangan bo‘lsa, o‘quvchi grafikdagi tendensiya, o‘zgarish va bog‘lanishni topib xulosa chiqarishi kerak. Faqat grafik turini yoddan aytish bu darajadagi fikrlashni tekshirmaydi. Shu sabab faoliyatning o‘zi ham tahlil va dalillangan xulosani talab qilishi maqsadga mos.'),
  ('revision:pedagogy:25ad0a5d-0e7c-40c4-b2ef-51232d7dfdea', 'Ota-ona bilan hamkorlikda markazda bolaning manfaatlari, rivojlanish ehtiyoji va dalilga asoslangan yechim turadi. O‘qituvchi kuzatuvlarni xolis aytib, oilaning fikrini tinglaydi va kelishilgan yordam qadamlarini belgilaydi. Ayblash yoki faqat baho haqida tortishish hamkorlikning maqsadidan chalg‘itadi.'),
  ('revision:pedagogy:2616bbee-8e7e-4052-ad03-eb0c3bf1aac4', 'Tarbiyaviy tadbirda o‘quvchilar faqat tomosha qilsa, ular mas’uliyatni amalda sinab ko‘rmaydi. Har biriga tashkilotchilik, taqdimot, kuzatuv yoki natijani baholash kabi mazmunli rol berish ishtirokni kuchaytiradi. Bu faoliyat davomida hamkorlik, javobgarlik va umumiy maqsadga hissa qo‘shish ko‘nikmalari shakllanadi.'),
  ('revision:pedagogy:2975b317-4210-41eb-b286-07446f5a01ca', 'O‘quvchining dars oxirida nimalarni bilib olgani, qayerda qiynalgani va keyingi safar nimani o‘zgartirishini yozishi metakognitiv refleksiyadir. Bola faqat bahosini takrorlamay, o‘z o‘rganish jarayonini kuzatadi va keyingi qadamini rejalashtiradi. Shu jihati bilan bu oddiy takrorlash yoki yakuniy nazorat emas.'),
  ('revision:pedagogy:2bc30a51-4e8e-472c-b568-a77ccccc6cd4', 'Xavfsiz ta’lim muhiti uch jihatni birlashtiradi: jismoniy xavfsizlikda jihoz va xona xavfi kamaytiriladi, psixologik xavfsizlikda qo‘rquv va kamsitishdan himoya qilinadi, ijtimoiy xavfsizlikda hurmatli munosabat va adolatli ishtirok ta’minlanadi. Faqat elektr simlarini tekshirish yoki intizom qoidasi bu tushunchani to‘liq qamramaydi.'),
  ('revision:pedagogy:2f8d9ea8-2738-4517-b1fd-de2246a2a8a2', 'Foizni real xarid xarajati bilan bog‘lash matematik hisobni iqtisodiy qarorga qo‘llash imkonini beradi. O‘quvchi nafaqat foizni topadi, balki natija qanday xarajat yoki tejashni anglatishini asoslaydi. Bu ikki fan nomini yonma-yon tilga olishdan farqli haqiqiy mazmuniy va kompetensiyaviy integratsiya hisoblanadi.'),
  ('revision:pedagogy:43d98352-77bf-426c-b8e0-5329246f8a9e', 'Bir xil topshiriq ayrim o‘quvchilarga juda oson, boshqalarga esa haddan tashqari qiyin bo‘lsa, umumiy maqsad saqlangan holda murakkablik va ko‘makni farqlash kerak. Biri tayanch qadamlar bilan, boshqasi mustaqil kengaytirilgan vazifa bilan ishlashi mumkin. Bunday differensiallash adolatni bir xil vazifa bilan emas, rivojlanishga mos imkon bilan ta’minlaydi.'),
  ('revision:pedagogy:4cfb892c-0215-4de9-a4d9-ecdc28bbd422', 'Nizo yuz berganda o‘qituvchi avvalo bolalarning xavfsizligini ta’minlab, zararli harakatni to‘xtatadi. Keyin har ikki tomonning fikrini xolis tinglab, voqea sababi va dalillarini aniqlaydi. Darhol aybdorni e’lon qilish yoki hammaga jazo berish nizoni adolatli hal etmasligi mumkin; keyingi kelishuv dalilga asoslanishi kerak.'),
  ('revision:pedagogy:4e020277-a633-472a-b166-72d56f2f2fc0', 'Hamkasb maslahatini sinab ko‘rish kasbiy rivojlanish jarayonining faqat bir qismidir. O‘qituvchi fikrlash vaqtini uzaytirgach, o‘quvchilar javob sifati va faolligi qanday o‘zgarganini kuzatishi, avvalgi natija bilan taqqoslashi zarur. Ana shu dalil asosida usulni davom ettirish yoki yangilash haqida xulosa qilish mumkin.'),
  ('revision:pedagogy:5e3047d5-03ce-464d-9df6-13dbbe4f8b93', 'Samarali darsda kutilgan o‘quv natijasi, unga erishish uchun bajariladigan faoliyat va natijani tekshiruvchi baholash bir-biriga mos bo‘ladi. Agar maqsad dastur tuzish bo‘lsa, o‘quvchi amalda kod yozishi va ishini mezon bilan tekshirtirishi kerak. Darsning qiziqarli o‘tishi bunday moslikning o‘rnini bosa olmaydi.'),
  ('revision:pedagogy:6f2336d3-9584-45ee-ac1f-150ff5d5b048', 'Sifatli qayta aloqa o‘quvchiga hozir nimani to‘g‘ri bajargani, aynan qayerda xato qilgani va qanday qadam bilan yaxshilanishi mumkinligini ko‘rsatadi. Masalan, «hisob usuli to‘g‘ri, birliklarni o‘zgartirishni tekshir» deyish aniq ko‘rsatmadir. Faqat ball yoki «yaxshi» degan baho esa keyingi harakatni tushuntirmaydi.'),
  ('revision:pedagogy:70c6f5bc-3969-4a06-8469-e7c6279bb6a1', 'O‘quvchining qiyinchiligi bir nechta fanda namoyon bo‘lsa, muammo faqat bitta dars metodidan kelib chiqmasligi mumkin. Tegishli fan o‘qituvchilari, zarur bo‘lganda mutaxassislar, aniq kuzatuvlarni solishtirib, yagona yordam rejasini tuzishi maqsadga muvofiq. Maxfiylikka rioya etish va bolaning ehtiyojini markazga qo‘yish shart.'),
  ('revision:pedagogy:75000000-0000-4000-8000-000000000004', 'Guruh topshiriqni bajara olmayotgan bo‘lsa, vazifani kichik va ketma-ket bosqichlarga ajratish, namuna ko‘rsatish hamda kerakli tayanch savollar bilan yordam berish foydali. O‘quvchilar mustaqilligi oshgani sari ko‘mak kamaytiriladi. Faqat javobni tayyor aytish yoki vazifani butunlay bekor qilish ko‘nikma rivojlanishini cheklashi mumkin.'),
  ('revision:pedagogy:75000000-0000-4000-8000-000000000005', 'Formativ baholashning maqsadi o‘qish jarayonida o‘quvchi nimani o‘zlashtirgani va qayerda qiynalayotganini aniqlab, shu zahoti foydali qayta aloqa berishdir. Natijadan keyin tushuntirish va mashqni moslashtirish mumkin. Bu faqat chorak oxirida yakuniy baho qo‘yishdan farq qiladi, chunki jarayonni davomida yaxshilashga xizmat qiladi.'),
  ('revision:pedagogy:75000000-0000-4000-8000-000000000007', 'Tarbiyaviy ishda o‘quvchining qadr-qimmatini saqlash uning xatosini yashirish emas, xulqini kamsitmasdan tuzatish demakdir. O‘qituvchi hamma bolaga hurmatli ohangda murojaat qilib, tanqidni shaxsiyatga emas, aniq xatti-harakatga qaratadi. Bu adolatli, psixologik xavfsiz muhitga xizmat qiladi.'),
  ('revision:pedagogy:75000000-0000-4000-8000-000000000008', 'Kamsitish holatida eng birinchi vazifa zararli muloqotni to‘xtatish va jabrlangan bolaning xavfsizligini ta’minlashdir. Keyin sinf uchun hurmatli muomala qoidalari eslatilib, holat alohida aniqlanadi va zarur yordam ko‘rsatiladi. Kamsitishni «oddiy hazil» deb e’tiborsiz qoldirish psixologik xavfsizlikni buzadi.'),
  ('revision:pedagogy:75000000-0000-4000-8000-000000000009', 'Kompyuter xonasida simlarning butunligi va o‘tish yo‘llarining ochiqligi jismoniy xavfsizlikning aniq shartlaridir. Shikastlangan kabel tok urishi, yo‘lakdagi sim esa yiqilish xavfini tug‘dirishi mumkin. Ularni darsdan oldin tekshirish va xavf aniqlansa bartaraf etish profilaktik choradir, faqat ogohlantirish yozuvi bilan cheklanib bo‘lmaydi.'),
  ('revision:pedagogy:75000000-0000-4000-8000-000000000011', 'Kasbiy rivojlanish rejasiga qaysi yo‘nalish kiritilishini faqat shaxsiy taassurotga qarab emas, bir nechta dalil asosida belgilash lozim. O‘quvchi natijalari amaliy samarani, o‘zini tahlil qilish ichki qiyinchilikni, hamkasb fikri esa tashqi kuzatuvni beradi. Ularni birga ko‘rib chiqish real o‘sish ehtiyojini ochadi.'),
  ('revision:pedagogy:75000000-0000-4000-8000-000000000012', 'Yangi baholash usuli kutilgan natija bermagan bo‘lsa, o‘qituvchi avval qaysi mezon yoki topshiriq ishlamaganini natija dalillari bilan aniqlashi kerak. So‘ng metodni moslashtirib, yana qo‘llaydi va o‘quvchi natijasini qayta kuzatadi. Xatoni inkor etish yoki usulni dalilsiz almashtirishdan farqli ravishda bu izchil refleksiya siklidir.'),
  ('revision:pedagogy:75000000-0000-4000-8000-000000000013', 'Ota-ona bilan o‘quvchi yutuqlarini muhokama qilishda faqat umumiy maqtov yoki kamchilik ro‘yxati yetarli emas. O‘qituvchi aniq bajarilgan ish, o‘sish ko‘rsatkichi va keyingi maqsadni hurmatli ohangda tushuntiradi; shaxsiy ma’lumotni zarur doirada saqlaydi. Oila bilan kelishilgan qadam bolaning rivojlanishini qo‘llab-quvvatlaydi.'),
  ('revision:pedagogy:75000000-0000-4000-8000-000000000014', 'Ikki fan o‘qituvchisi raqamli loyiha tuzganda avval umumiy o‘quv maqsadini kelishishi, har bir fan qanday hissa qo‘shishini va kim nima uchun mas’ul ekanini aniqlashi zarur. Baholash mezoni ham oldindan belgilansa, ish takrorlanmaydi va o‘quvchi natijasi xolisroq tekshiriladi. Faqat sana tanlash hamkorlikni kafolatlamaydi.'),
  ('revision:pedagogy:79000000-0000-4000-8000-000000000105', 'O‘quvchining shaxsiy ma’lumoti ruxsatsiz tarqatilganda tarqatishni imkon qadar tez to‘xtatish, bolaning xavfsizligi va ruhiy holatini qo‘llab-quvvatlash birinchi o‘rinda turadi. Zarur dalillarni ehtiyotkor saqlab, maktabdagi vakolatli mas’ulga xabar berish kerak. Holatni barcha sinfga oshkor qilish maxfiylikni yanada buzishi mumkin.'),
  ('revision:pedagogy:79000000-0000-4000-8000-000000000106', 'Ekrandagi matnni o‘qish qiyin bo‘lgan o‘quvchiga kattaroq shrift, mos kontrast, ovozli o‘qish yoki yordamchi texnologiya taklif etish mumkin. Bu o‘quv maqsadini pasaytirish emas, materialga kirish yo‘lini moslashtirishdir. Inklyuziv informatika darsida har bir o‘quvchi bir xil muhim ko‘nikmaga erisha olishiga e’tibor qaratiladi.'),
  ('revision:pedagogy:79300000-0000-4000-8000-000000000326', 'Farzandining qiyinchiligini eshitayotgan ota-onaga «u dangasa» kabi yorliq emas, aniq kuzatuv va bajarilgan ish natijalari aytilishi kerak. Mavjud kuchli tomonlar ham ko‘rsatilib, qiyinchilikni kamaytirish uchun uy va maktabda bajariladigan qadamlar kelishiladi. Hurmatli, dalilga tayangan hamkorlik oilaning ishonchini saqlaydi.'),
  ('revision:pedagogy:7ec163c0-a7dc-44d3-b1f4-cff475c7f7dd', 'Dars rejasi batafsil bo‘lsa ham, baholash usuli maqsadda ko‘rsatilgan ko‘nikmani tekshirmasa, uning sifati yetarli emas. Masalan, amaliy dastur tuzish maqsadiga faqat ta’rif so‘rash mos kelmaydi. Rejalashda qanday o‘quvchi ishi natija dalili bo‘lishi va qanday mezon bilan tekshirilishi oldindan belgilanadi.'),
  ('revision:pedagogy:81b8a6de-72ae-4884-9c71-457474f56609', 'Boshqa o‘quvchining baholari va xulqi shaxsiy ma’lumot hisoblanadi; ularni uchinchi shaxsga shunchaki qiziqish uchun aytish mumkin emas. O‘qituvchi ota-onaning o‘z farzandiga tegishli savollarini muhokama qiladi va boshqa bolaga oid maxfiy axborotni oshkor etmaydi. Bu kasbiy etika va ishonchli hamkorlikning shartidir.'),
  ('revision:pedagogy:963717dd-c758-4057-8621-05238b92bc52', 'Metakognitiv refleksiya o‘quvchining faqat qanday natijaga erishganini emas, qanday usul bilan o‘rganganini ham anglashiga xizmat qiladi. Bola muvaffaqiyatli strategiya va qiyinchilik sababini aniqlab, keyingi vazifa uchun reja tuzadi. Shu sabab bu oddiy o‘zini maqtash yoki bahoni qayta aytishdan kengroq faoliyatdir.'),
  ('revision:pedagogy:9876b15e-7412-45a3-8da5-71f294caf21c', 'Tarbiyaviy tadbirda yuz bergan intizom muammosi uchun barcha bolaga bir xil jazo berish har kimning xatti-harakati va sababini farqlamaydi. Bu adolatsizlik hissini kuchaytirishi va xulqni yaxshilamasligi mumkin. Avval vaziyat, mas’uliyat va zarar aniqlanib, aniq hamda hurmatli tarbiyaviy chora tanlanishi kerak.'),
  ('revision:pedagogy:992bb41b-8201-4e64-bc5f-166f1288ab09', 'Interfaol metod faqat o‘quvchilarni band qilish uchun emas, belgilangan bilim va ko‘nikmani shakllantirish uchun tanlanadi. Agar o‘yin mavzu maqsadiga aloqasiz bo‘lsa, faollik tashqi ko‘rinishda qoladi. Metod samaradorligini o‘quvchilar qanday dalil, xulosa yoki amaliy natija yaratgani orqali tekshirish kerak.'),
  ('revision:pedagogy:b41963b6-c602-47ab-8a03-85e82ba5f9c8', 'Diagnostika sinfning yarmi zarur tayanch bilimga ega emasligini ko‘rsatganida yangi mavzu sur’atini o‘zgartirmasdan davom etish qiyinchilikni chuqurlashtirishi mumkin. O‘qituvchi qisqa takrorlash, bosqichli ko‘mak va differensial topshiriqni rejalaydi. Shunda tayyor o‘quvchilar ham, yordamga muhtojlar ham rivojlanadi.'),
  ('revision:pedagogy:bedabf19-18e8-4368-8234-453c52ef9a9a', 'Guruhda bitta bola barcha ishni bajarsa, boshqalar jarayondan o‘rganmasligi mumkin. Vazifani aniq rollarga ajratish, har bir a’zodan o‘z hissasini tushuntirishni so‘rash va umumiy natija uchun javobgarlikni belgilash kerak. Bu guruh shaklini haqiqiy hamkorlikka aylantirib, teng va mazmunli ishtirok yaratadi.'),
  ('revision:pedagogy:c593ff16-733b-4966-ae7d-01bbdf96593a', 'O‘quvchi bir xil xatoni takrorlasa, faqat «noto‘g‘ri» deyish sababni bartaraf etmaydi. U tushunchani noto‘g‘ri anglayaptimi, qadamni o‘tkazyaptimi yoki topshiriqni shoshilib o‘qiyaptimi, aniqlash lozim. So‘ng xatoga mos amaliy tavsiya va qisqa mashq berilib, natija qayta tekshiriladi.'),
  ('revision:pedagogy:c7a9875d-d5ab-47d5-a294-434d6631515d', 'Monitoring o‘quvchi, sinf yoki ta’lim jarayonidagi o‘zgarishni ma’lum vaqt davomida muntazam va bir xil mezonlar bilan kuzatishdir. Bir martalik test faqat o‘sha paytdagi holatni ko‘rsatishi mumkin; takroriy kuzatuv esa rivojlanish yo‘nalishini ochadi. Shunga tayangan holda yordam va reja o‘z vaqtida moslashtiriladi.'),
  ('revision:pedagogy:c9f321e4-be11-4091-aa09-1f51233d5430', 'Hamkorlik maxfiylikni bekor qilmaydi: o‘quvchi haqidagi ma’lumot faqat aniq ta’limiy vazifani bajarishi kerak bo‘lgan vakolatli tomonlarga zarur hajmda beriladi. Barcha yozishmalarni umumiy guruhga yuborish yoki boshqa bolaning natijasini aytish shart emas. Maqsadga muvofiq cheklangan almashinuv ishonchni saqlaydi.'),
  ('revision:pedagogy:ca4238ec-b464-44d8-9088-7772491b6b53', '8-sinfda dastlabki tekshiruv ayrimlar tushunchani bilishini, boshqalar esa uni amalda qo‘llashda qiynalayotganini ko‘rsatgan. Shuning uchun bir guruhga tayanch qadamlar va qo‘llanmali mashq, boshqasiga murakkabroq mustaqil vazifa berish mumkin. Bu dars maqsadini saqlab, yordamni haqiqiy tayyorgarlikka moslaydi.'),
  ('revision:pedagogy:ce5dc496-b4a2-4038-b541-b451cd12bbef', 'Amaliy ko‘nikma darsida vaqtning 90 foizi o‘qituvchi gapirishiga sarflansa, o‘quvchida mustaqil bajarish va xatoni tuzatish imkoniyati kam qoladi. Qisqa namuna, bosqichli mashq va mustaqil ishga yetarli vaqt ajratish zarur. Faqat tushuntirishni uzaytirish ko‘nikma shakllanishini ta’minlamaydi.'),
  ('revision:pedagogy:d1b8b7c1-4e76-429c-b4e9-cd509d038259', 'Kasbiy refleksiya taxmin yoki «menga darsim yoqdi» degan taassurot bilan cheklanmasligi kerak. O‘quvchi ishlari, baholash natijalari, kuzatuv yozuvlari va hamkasb qayta aloqasi pedagogik qarorni asoslaydi. Shu dalillar kuchli va zaif jihatni ajratib, keyingi darsda nimani o‘zgartirish kerakligini aniqlashga yordam beradi.'),
  ('revision:pedagogy:d35bd047-1f02-4305-88c3-a10ccaa19a8f', 'Farzandining past bahosidan norozi ota-onaga o‘qituvchi xotirjam, aniq dalillar bilan javob beradi, oilaning xavotirini tinglaydi va qiyinchilik sababini birgalikda tahlil qiladi. Keyin qanday mashq, yordam va nazorat muddati kerakligini kelishadi. Bahs yoki o‘quvchini ayblash o‘rniga konstruktiv hamkorlik shakllanadi.'),
  ('revision:pedagogy:de6c80a4-96c0-46d6-86b9-7d83c4b871d6', 'Ekologik tozalash tadbirida faqat buyruqni bajarish bolaning nima uchun harakat qilayotganini anglashini kafolatlamaydi. Ishdan keyin atrof-muhitga ta’sir, shaxsiy mas’uliyat va natijani birgalikda muhokama qilish tarbiyaviy ma’noni ochadi. Refleksiya tashqi topshiriqni ongli ekologik qadriyatga bog‘laydi.'),
  ('revision:pedagogy:df86a484-666e-470a-8e26-5205e5f3cd27', '«6/10» soni xatoni qanday tuzatishni ko‘rsatmaydi. «Formulani to‘g‘ri tanlading, lekin birliklarni aylantirishni tekshir; 2–3-masalani qayta ishlagin» degan izoh esa kuchli jihat, aniq kamchilik va bajariladigan keyingi qadamni birlashtiradi. Shu sabab bunday qayta aloqa o‘qishni yaxshilashga ko‘proq xizmat qiladi.'),
  ('revision:pedagogy:e0381c05-5a3c-4641-9c57-6efc8e84f274', 'Inklyuziv sinfda bolalarning tili, tayyorgarligi va qo‘llab-quvvatlash ehtiyoji turlicha bo‘lishi tabiiy. Pedagog asosiy o‘quv natijasini saqlab, ko‘rsatma formati, yordam darajasi va qatnashish usulini moslashtiradi. Maqsad hammani aynan bir xil yo‘lda ishlatish emas, har biri uchun teng va mazmunli o‘rganish imkonini yaratishdir.'),
  ('revision:pedagogy:edab125b-22ca-4045-99ae-8178040af3aa', 'Kompyuter xonasida yo‘lakdan o‘tgan kabel o‘quvchilar yiqilishi yoki jihozning tortilib ketishi xavfini tug‘diradi. O‘qituvchi ishni xavfsiz to‘xtatib, kabelni to‘g‘ri joylashtirish va foydalanish sharoitini tiklash choralarini ko‘rishi kerak. Faqat ehtiyot bo‘lishni aytish xavfni bartaraf qilmaydi.'),
  ('revision:pedagogy:f46fea20-425b-4db9-a73b-6d2fbd0835eb', 'Tarmoqda haqoratli xabar olgan o‘quvchi avvalo zararli aloqadan himoyalanishi va ishonchli kattalardan yordam olishi kerak. Dalillarni ehtiyotkor saqlash, xabarni tegishli tartibda bildirish va bolaning maxfiyligini hurmat qilish muhim. Vaziyatni sinfda oshkor qilish yoki bolani o‘zi aybdor deb ko‘rish zararli bo‘lishi mumkin.');
